CREATE FUNCTION archive_piece() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  INSERT INTO archive_pieces VALUES (OLD.id, OLD.affaire, OLD.description, LOCALTIMESTAMP(0));
  RETURN OLD;
END;
$$;
CREATE TRIGGER trg_archive AFTER DELETE ON pieces FOR EACH ROW EXECUTE FUNCTION archive_piece();
