CREATE FUNCTION journalise_modif() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  INSERT INTO journal_brigade (login, action, table_cible, ligne_id, ancienne_valeur, horodatage)
  VALUES ('trigger', 'UPDATE', 'pieces', OLD.id, to_jsonb(OLD.description), LOCALTIMESTAMP(0));
  RETURN NEW;
END;
$$;
CREATE TRIGGER trg_modif AFTER UPDATE ON pieces FOR EACH ROW EXECUTE FUNCTION journalise_modif();
